; picture.asm -- chapter 15: a picture, with INCBIN
; generated by gen15.py
        INCLUDE "msx.inc"
        OUTPUT "picture.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; A picture put into the cartridge by the assembler, and sent to Graphic
; II's patterns as it is, with the display off (chapter 13).
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VDP_REG 7, LIGHT_GREEN  ; the border: where the picture ends shows
        VRAM_WRITE $0000        ; the patterns, from the first
        ld hl, picture
        ld c, VDP_DATA
        ld d, 24                ; 24 times 256 bytes
        ld b, 0
p1:     otir                    ; 256 bytes to the VDP (chapter 13)
        dec d
        jr nz, p1
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

picture:
        INCBIN "picture.bin"    ; 6,144 bytes, as they are in the file
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
